import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def swizzle_tile(
    tile_id,
    M,
    N,
    K,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    grid_m = tl.cdiv(M, BLOCK_M)
    grid_n = tl.cdiv(N, BLOCK_N)
    width = GROUP_SIZE_M * grid_n
    group_id = tile_id // width
    group_size = tl.minimum(GROUP_SIZE_M, grid_m - group_id * GROUP_SIZE_M)
    pid_m = group_id * GROUP_SIZE_M + (tile_id % group_size)
    pid_n = (tile_id % width) // group_size
    return pid_m, pid_n


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": gs},
        )
        for gs in [1, 2, 4, 8]
    ],
    key=["M", "N", "K"],
)
@triton.jit
def _triu_matmul_kernel(
    a_ptr,
    b_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am: tl.constexpr,
    stride_ak: tl.constexpr,
    stride_bk: tl.constexpr,
    stride_bn: tl.constexpr,
    stride_cm: tl.constexpr,
    stride_cn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    pid = tl.program_id(0)
    pid_m, pid_n = swizzle_tile(pid, M, N, K, BLOCK_M, BLOCK_N, BLOCK_K, GROUP_SIZE_M)

    off_m = pid_m * BLOCK_M
    off_n = pid_n * BLOCK_N

    # Skip tiles entirely below the diagonal (output is upper triangular)
    if off_m >= off_n + BLOCK_N:
        return

    # K-loop trimming: A is upper tri so A[i,k]=0 for k<i, B is upper tri so B[k,j]=0 for k>j
    # Effective K range: [off_m, min(off_n + BLOCK_N, K))
    k_start = (off_m // BLOCK_K) * BLOCK_K
    k_end_raw = off_n + BLOCK_N
    k_end = k_end_raw if k_end_raw < K else K

    a_desc = tl.make_tensor_descriptor(
        base=a_ptr,
        shape=(M, K),
        strides=(stride_am, stride_ak),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    b_desc = tl.make_tensor_descriptor(
        base=b_ptr,
        shape=(K, N),
        strides=(stride_bk, stride_bn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)

    for k_offset in range(k_start, k_end, BLOCK_K):
        a_block = a_desc.load([off_m, k_offset])
        b_block = b_desc.load([k_offset, off_n])
        acc += tl.dot(a_block, b_block)
    # Apply triu mask
    row_idx = off_m + tl.arange(0, BLOCK_M)
    col_idx = off_n + tl.arange(0, BLOCK_N)
    triu_mask = row_idx[:, None] <= col_idx[None, :]
    acc = tl.where(triu_mask, acc, 0.0)

    c_desc = tl.make_tensor_descriptor(
        base=c_ptr,
        shape=(M, N),
        strides=(stride_cm, stride_cn),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    c_desc.store([off_m, off_n], acc.to(c_ptr.type.element_ty))


class Model(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        M, K = A.shape
        N = B.shape[1]
        C = torch.zeros((M, N), device=A.device, dtype=A.dtype)

        def grid(META):
            assert (
                M % META["BLOCK_M"] == 0
                and N % META["BLOCK_N"] == 0
                and K % META["BLOCK_K"] == 0
            ), (
                "M, N, and K must be divisible by BLOCK_M, BLOCK_N, and BLOCK_K respectively"
            )
            return (triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),)

        _triu_matmul_kernel[grid](
            A,
            B,
            C,
            M,
            N,
            K,
            A.stride(0),
            A.stride(1),
            B.stride(0),
            B.stride(1),
            C.stride(0),
            C.stride(1),
            assume_in_bounds=True,
        )
        return C


N = 4096


def get_inputs():
    A = torch.triu(torch.rand(N, N, dtype=torch.bfloat16))
    B = torch.triu(torch.rand(N, N, dtype=torch.bfloat16))
    return [A, B]


